1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    :root {
9	      --color-white: #ffffff;
10	      --color-gold: #ffd700;
11	      --color-pink: #ff6b9d;
12	      --color-teal: #4ecdc4;
13	      --color-mint: #95e1d3;
14	      --shadow-color: rgba(0, 0, 0, 0.3);
15	      --transition-normal: 0.3s ease;
16	      --transition-slow: 0.6s ease-out;
17	      --color-mode-1-rgb: 255, 107, 157;
18	      --color-mode-2-rgb: 78, 205, 196;
19	      --color-mode-3-rgb: 149, 225, 211;
20	    }
21	
22	    * {
23	      margin: 0;
24	      padding: 0;
25	      box-sizing: border-box;
26	    }
27	    html, body {
28	      width: 100%;
29	      height: 100%;
30	      overflow: hidden;
31	    }
32	    body {
33	      display: flex;
34	      flex-direction: column;
35	      justify-content: center;
36	      align-items: center;
37	      gap: 20px;
38	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
39	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
40	      color: var(--color-white);
41	      font-size: 14px;
42	      text-align: center;
43	      padding: 20px;
44	    }
45	    .circle-container {
46	      cursor: pointer;
47	      border: none;
48	      background: none;
49	      padding: 0;
50	      position: relative;
51	      will-change: transform;
52	    }
53	    .circle-container:hover,
54	    .circle-container:focus-visible {
55	      transform: scale(1.08);
56	    }
57	    .circle-container:focus {
58	      outline: none;
59	    }
60	    .circle-container:focus-visible {
61	      outline: 3px solid rgba(255, 255, 255, 0.7);
62	      outline-offset: 12px;
63	      border-radius: 50%;
64	    }
65	    svg {
66	      width: min(400px, 80vw);
67	      height: min(400px, 80vw);
68	      display: block;
69	      animation: fadeIn var(--transition-slow);
70	    }
71	    circle {
72	      fill: var(--color-white);
73	      stroke: rgba(255, 255, 255, 0.2);
74	      stroke-width: 2;
75	      animation: pulse 3s ease-in-out infinite;
76	      filter: drop-shadow(0 20px 40px var(--shadow-color));
77	      transition: fill var(--transition-normal), r 0.3s ease, stroke var(--transition-normal), filter var(--transition-normal);
78	    }
79	    .circle-container:hover circle,
80	    .circle-container:focus-visible circle {
81	      fill: #e8f4f8;
82	      r: 205;
83	      stroke: rgba(255, 255, 255, 0.4);
84	    }
85	    .circle-container.active circle {
86	      fill: var(--color-gold);
87	      stroke: rgba(255, 215, 0, 0.3);
88	      animation: pulse-active 0.6s ease-in-out;
89	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
90	    }
91	    .circle-container.active:hover circle {
92	      fill: #ffed4e;
93	    }
94	
95	    .circle-container.color-mode-1 circle { fill: var(--color-pink); stroke: rgba(var(--color-mode-1-rgb), 0.3); filter: drop-shadow(0 20px 40px rgba(var(--color-mode-1-rgb), 0.3)); }
96	    .circle-container.color-mode-1:hover circle,
97	    .circle-container.color-mode-1:focus-visible circle { stroke: rgba(var(--color-mode-1-rgb), 0.5); }
98	    .circle-container.color-mode-1.active circle { filter: drop-shadow(0 20px 40px rgba(var(--color-mode-1-rgb), 0.5)); }
99	
100	    .circle-container.color-mode-2 circle { fill: var(--color-teal); stroke: rgba(var(--color-mode-2-rgb), 0.3); filter: drop-shadow(0 20px 40px rgba(var(--color-mode-2-rgb), 0.3)); }
101	    .circle-container.color-mode-2:hover circle,
102	    .circle-container.color-mode-2:focus-visible circle { stroke: rgba(var(--color-mode-2-rgb), 0.5); }
103	    .circle-container.color-mode-2.active circle { filter: drop-shadow(0 20px 40px rgba(var(--color-mode-2-rgb), 0.5)); }
104	
105	    .circle-container.color-mode-3 circle { fill: var(--color-mint); stroke: rgba(var(--color-mode-3-rgb), 0.3); filter: drop-shadow(0 20px 40px rgba(var(--color-mode-3-rgb), 0.3)); }
106	    .circle-container.color-mode-3:hover circle,
107	    .circle-container.color-mode-3:focus-visible circle { stroke: rgba(var(--color-mode-3-rgb), 0.5); }
108	    .circle-container.color-mode-3.active circle { filter: drop-shadow(0 20px 40px rgba(var(--color-mode-3-rgb), 0.5)); }
109	
110	    .hint {
111	      font-size: 12px;
112	      opacity: 0.8;
113	      transition: opacity var(--transition-normal);
114	      letter-spacing: 0.5px;
115	      max-width: 85%;
116	      line-height: 1.4;
117	    }
118	    .circle-container:hover ~ .hint,
119	    .circle-container:focus-visible ~ .hint {
120	      opacity: 1;
121	    }
122	
123	    .mode-indicator {
124	      font-size: 10px;
125	      opacity: 0;
126	      margin-top: 8px;
127	      letter-spacing: 1px;
128	      text-transform: uppercase;
129	      transition: opacity var(--transition-normal);
130	      height: 16px;
131	    }
132	    .mode-indicator.visible {
133	      opacity: 0.9;
134	    }
135	
136	    .controls {
137	      display: flex;
138	      gap: 12px;
139	      margin-top: 8px;
140	    }
141	
142	    .control-btn {
143	      padding: 8px 16px;
144	      font-size: 11px;
145	      font-weight: 600;
146	      letter-spacing: 0.5px;
147	      text-transform: uppercase;
148	      background: rgba(255, 255, 255, 0.15);
149	      color: var(--color-white);
150	      border: 1px solid rgba(255, 255, 255, 0.3);
151	      border-radius: 20px;
152	      cursor: pointer;
153	      transition: all var(--transition-normal);
154	      backdrop-filter: blur(4px);
155	      will-change: transform;
156	    }
157	
158	    .control-btn:hover {
159	      background: rgba(255, 255, 255, 0.25);
160	      border-color: rgba(255, 255, 255, 0.5);
161	      transform: translateY(-2px);
162	    }
163	
164	    .control-btn:active {
165	      transform: scale(0.95);
166	    }
167	    .control-btn:focus {
168	      outline: none;
169	    }
170	    .control-btn:focus-visible {
171	      outline: 2px solid rgba(255, 255, 255, 0.7);
172	      outline-offset: 4px;
173	    }
174	    @keyframes pulse {
175	      0%, 100% { r: 200; opacity: 0.95; }
176	      50% { r: 203; opacity: 1; }
177	    }
178	    @keyframes pulse-active {
179	      0% { r: 200; }
180	      50% { r: 210; }
181	      100% { r: 200; }
182	    }
183	    @keyframes fadeIn {
184	      from { opacity: 0; transform: scale(0.9); }
185	      to { opacity: 1; transform: scale(1); }
186	    }
187	    @keyframes colorShift {
188	      0% { filter: saturate(1); }
189	      50% { filter: saturate(1.4); }
190	      100% { filter: saturate(1); }
191	    }
192	    .color-shifting circle {
193	      animation: colorShift 0.6s ease-out;
194	    }
195	    @media (max-width: 480px) {
196	      body {
197	        gap: 16px;
198	      }
199	      .hint {
200	        font-size: 11px;
201	      }
202	      .mode-indicator {
203	        font-size: 9px;
204	      }
205	    }
206	    @media (prefers-reduced-motion: reduce) {
207	      * {
208	        animation: none !important;
209	        transition: none !important;
210	      }
211	    }
212	  </style>
213	</head>
214	<body>
215	  <main style="text-align: center;">
216	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle">
217	      <svg viewBox="0 0 400 400" aria-hidden="true">
218	        <circle cx="200" cy="200" r="200"/>
219	      </svg>
220	    </button>
221	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
222	    <div class="controls">
223	      <button class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
224	      <button class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
225	    </div>
226	  </main>
227	  <div class="hint" id="hint-text" role="status" aria-live="polite">Click to activate • Double-click to change color</div>
228	
229	  <script>
230	    const STORAGE_KEY = 'circle-state';
231	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
232	    const COLOR_NAMES = ['Default White', 'Pink', 'Teal', 'Mint'];
233	    const IS_TOUCH = (('ontouchstart' in window) || (navigator.maxTouchPoints > 0) || (navigator.msMaxTouchPoints > 0));
234	    const TAP_DELAY = 300;
235	    const COLOR_SHIFT_DURATION = 600;
236	
237	    const elements = {
238	      circle: document.getElementById('decorative-circle'),
239	      hint: document.getElementById('hint-text'),
240	      modeIndicator: document.getElementById('mode-indicator'),
241	      cycleBtn: document.getElementById('cycle-btn'),
242	      resetBtn: document.getElementById('reset-btn')
243	    };
244	
245	    let state = { active: false, colorMode: 0 };
246	    let lastTapTime = 0;
247	
248	    const storage = {
249	      save: () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state)),
250	      load: () => {
251	        try {
252	          const saved = localStorage.getItem(STORAGE_KEY);
253	          if (saved) state = JSON.parse(saved);
254	        } catch (e) {
255	          console.warn('Failed to load state');
256	        }
257	      }
258	    };
259	
260	    const updateClasses = () => {
261	      elements.circle.classList.remove('active', ...COLOR_MODES);
262	      if (state.active) elements.circle.classList.add('active');
263	      if (state.colorMode > 0) elements.circle.classList.add(COLOR_MODES[state.colorMode]);
264	    };
265	
266	    const updateUI = () => {
267	      const hints = state.active
268	        ? ['Active!', IS_TOUCH ? 'Tap again to change color' : 'Double-click or C to change color', IS_TOUCH ? 'Use Reset' : 'Press R to reset']
269	        : ['Click to activate', IS_TOUCH ? 'Tap twice for color' : 'Double-click or C to cycle', 'Use Reset'];
270	      elements.hint.textContent = hints.join(' • ');
271	
272	      if (state.active && state.colorMode > 0) {
273	        elements.modeIndicator.textContent = COLOR_NAMES[state.colorMode];
274	        elements.modeIndicator.classList.add('visible');
275	      } else {
276	        elements.modeIndicator.classList.remove('visible');
277	      }
278	    };
279	
280	    const applyState = () => {
281	      updateClasses();
282	      updateUI();
283	    };
284	
285	    const toggleActive = () => {
286	      state.active = !state.active;
287	      applyState();
288	      storage.save();
289	    };
290	
291	    const cycleColor = () => {
292	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
293	      state.active = true;
294	      elements.circle.classList.add('color-shifting');
295	      setTimeout(() => elements.circle.classList.remove('color-shifting'), COLOR_SHIFT_DURATION);
296	      applyState();
297	      storage.save();
298	    };
299	
300	    const resetState = () => {
301	      state = { active: false, colorMode: 0 };
302	      applyState();
303	      storage.save();
304	    };
305	
306	    const handleDblClick = (e) => {
307	      e.preventDefault();
308	      cycleColor();
309	    };
310	
311	    const handleTouchEnd = (e) => {
312	      const currentTime = Date.now();
313	      const tapLength = currentTime - lastTapTime;
314	      if (tapLength < TAP_DELAY && tapLength > 0) {
315	        e.preventDefault();
316	        cycleColor();
317	      } else {
318	        lastTapTime = currentTime;
319	      }
320	    };
321	
322	    const handleKeyDown = (e) => {
323	      const key = e.key.toLowerCase();
324	      if (key === ' ' || key === 'enter') {
325	        e.preventDefault();
326	        toggleActive();
327	      } else if (key === 'c') {
328	        e.preventDefault();
329	        cycleColor();
330	      } else if (key === 'r') {
331	        e.preventDefault();
332	        resetState();
333	      }
334	    };
335	
336	    elements.circle.addEventListener('click', toggleActive);
337	    elements.circle.addEventListener('dblclick', handleDblClick);
338	    elements.circle.addEventListener('touchend', handleTouchEnd);
339	    elements.circle.addEventListener('keydown', handleKeyDown);
340	    elements.cycleBtn.addEventListener('click', cycleColor);
341	    elements.resetBtn.addEventListener('click', resetState);
342	
343	    storage.load();
344	    applyState();
345	    elements.circle.focus();
346	  </script>
347	</body>
348	</html>
